+        this.user = user;
+    }
+
+    @Override
+    public boolean equals(Object o) {
+        if (this == o) {
+            return true;
+        }
+        if (!(o instanceof PasswordHistory)) {
+            return false;
+        }
+        return id != null && id.equals(((PasswordHistory) o).id);
+    }
+
+    @Override
+    public int hashCode() {
+        return 31;
+    }
