+        return (
+            "PasswordHistory{" +
+            "id=" +
+            getId() +
+            ", passwordHash='" +
+            getPasswordHash() +
+            "'" +
+            ", createdDate='" +
+            getCreatedDate() +
+            "'" +
+            "}"
+        );
+    }
+}

