+
+    static final String TEST_USER_LOGIN = "test-user";
+    static final String TEST_USER_PASSWORD = "test-password";
+
+    @Autowired
+    private UserRepository userRepository;
+
+    @Autowired
+    private PasswordEncoder passwordEncoder;
