+			jdbcPet.setOwner(EntityUtils.getById(owners, Owner.class, jdbcPet.getOwnerId()));
+			// TODO add visits
+			pets.add(jdbcPet);
+		}
+
+		return new PageImpl<>(pets, pageable, totalCount);
+	}
