+	@Test
+	void testApiKeyAuthentication_NullKey() throws Exception {
+		// Create a request without an API key
+		MvcResult result = mockMvc.perform(get("/partners/test"))
+			.andExpect(status().isUnauthorized())
+			.andReturn();
